const path = require("path");
const fs   = require("fs");

const W = 1200;
const H = 630;
const PINK       = "#FC74FE";
const DARK       = "#0D0D0D";
const GRAY       = "#6B7280";
const GRAY_LIGHT = "#9CA3AF";
const WHITE      = "#FFFFFF";
const BG_COLOR   = "#FEF4FF";

const LEFT_BG = "data:image/jpeg;base64,";

function bufToB64(buf) { return Buffer.from(buf).toString("base64"); }

async function fetchToken(contract) {
  const def = { name: "Unknown Token", symbol: "TOKEN", logoURI: null };
  if (!contract) return def;
  try {
    const r = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${contract}`,
      { signal: AbortSignal.timeout(5000) });
    if (!r.ok) return def;
    const d = await r.json();
    const p = d?.pairs?.[0];
    if (!p) return def;
    return { name: p.baseToken?.name || "Unknown Token",
             symbol: p.baseToken?.symbol || "TOKEN",
             logoURI: p.info?.imageUrl || null };
  } catch { return def; }
}

async function fetchLogo(url) {
  if (!url) return null;
  try {
    const r = await fetch(url, { signal: AbortSignal.timeout(4000) });
    if (!r.ok) return null;
    const buf = await r.arrayBuffer();
    if (buf.byteLength > 300000) return null;
    const ct = r.headers.get("content-type") || "image/png";
    return `data:${ct};base64,${bufToB64(buf)}`;
  } catch { return null; }
}

const dv = (style, children) => ({ type: "div", props: { style, children } });
const im = (src, w, h, st) => ({ type: "img", props: { src, width: w, height: h, style: st || {} } });

// Иконка подарка через SVG (нет зависимости от emoji шрифта)
const giftIcon = () => dv({
  width: 26, height: 26, display: "flex", flexDirection: "column",
  alignItems: "center", justifyContent: "center", gap: 2,
}, [
  // Верхняя часть подарка (крышка)
  dv({ width: 24, height: 8, backgroundColor: PINK, borderRadius: 2 }, ""),
  // Нижняя часть (коробка)
  dv({ width: 20, height: 12, backgroundColor: PINK, borderRadius: "0 0 2px 2px" }, ""),
]);

function render(name, ticker, logoURI) {
  const fs2 = name.length > 20 ? 34 : name.length > 15 ? 44
            : name.length > 10 ? 56 : name.length > 7 ? 66 : 74;

  const logo = logoURI
    ? im(logoURI, 230, 230, { borderRadius: "50%", objectFit: "cover" })
    : dv({ width: 230, height: 230, borderRadius: "50%", backgroundColor: PINK,
           display: "flex", alignItems: "center", justifyContent: "center",
           fontSize: 72, fontWeight: 700, color: WHITE },
         name.slice(0, 2).toUpperCase());

  return dv({
    display: "flex", flexDirection: "row",
    width: W, height: H, backgroundColor: BG_COLOR,
    fontFamily: "Liberation",
  }, [
    // ── ЛЕВАЯ: макет + логотип
    dv({ position: "relative", width: 440, height: H,
         flexShrink: 0, display: "flex", marginRight: -2 }, [
      im(LEFT_BG, 440, H, { position: "absolute", top: 0, left: 0 }),
      // Белый круг точно поверх единорога: center=(282,308), r=115
      // left=282-115=167, top=308-115=193, size=230x230
      dv({ position: "absolute", left: 167, top: 193, width: 230, height: 230,
           borderRadius: "50%", backgroundColor: WHITE,
           display: "flex", alignItems: "center", justifyContent: "center",
           overflow: "hidden" }, [logo]),
    ]),

    // ── ПРАВАЯ: карточка
    dv({
      display: "flex", flexDirection: "column", justifyContent: "center",
      flex: 1, height: H, backgroundColor: WHITE,
      borderRadius: "24px 0 0 24px", padding: "0 52px",
    }, [
      dv({ fontSize: fs2, fontWeight: 700, color: DARK, lineHeight: 1.05, marginBottom: 10 }, name),
      dv({ fontSize: 28, fontWeight: 700, color: PINK, marginBottom: 14 }, ticker),
      dv({ fontSize: 22, color: GRAY, marginBottom: 22 }, "Community Airdrop"),
      dv({ height: 1, backgroundColor: "rgba(19,19,19,0.08)", marginBottom: 18 }, ""),
      dv({ display: "flex", flexDirection: "row", alignItems: "center", gap: 14, marginBottom: 26 }, [
        dv({ width: 48, height: 48, borderRadius: "50%",
             backgroundColor: "rgba(252,116,254,0.12)",
             display: "flex", alignItems: "center", justifyContent: "center",
             flexShrink: 0 }, [giftIcon()]),
        dv({ display: "flex", flexDirection: "column", gap: 3 }, [
          dv({ fontSize: 18, fontWeight: 700, color: DARK }, "Claim your tokens"),
          dv({ fontSize: 13, color: GRAY_LIGHT },
             "Distributed to eligible community members via Uniswap Protocol"),
        ]),
      ]),
      dv({ backgroundColor: PINK, borderRadius: 100,
           display: "flex", alignItems: "center", justifyContent: "center",
           padding: "18px 0", marginBottom: 12 },
         dv({ fontSize: 20, fontWeight: 700, color: WHITE }, "Claim Now")),
      dv({ fontSize: 13, color: GRAY_LIGHT, textAlign: "center" }, "Claim via Uniswap Protocol"),
    ]),
  ]);
}

exports.handler = async (event) => {
  const { ImageResponse } = await import("@vercel/og");

  const contract = event.queryStringParameters?.contract || "";
  console.log("og-image:", contract);

  try {
    // Шрифт из файла рядом с функцией
    const fontPath = path.join(__dirname, "font.ttf");
    const fontData = fs.readFileSync(fontPath);

    const tok    = await fetchToken(contract);
    const logo   = await fetchLogo(tok.logoURI);
    const ticker = tok.symbol.startsWith("$") ? tok.symbol : `$${tok.symbol}`;

    const ir = new ImageResponse(render(tok.name, ticker, logo), {
      width: W, height: H,
      fonts: [{ name: "Liberation", data: fontData, weight: 700, style: "normal" }],
    });
    const png = Buffer.from(await ir.arrayBuffer());

    return {
      statusCode: 200,
      headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=3600" },
      body: png.toString("base64"),
      isBase64Encoded: true,
    };
  } catch (err) {
    console.error("ERROR:", err?.message);
    return {
      statusCode: 500,
      headers: { "Content-Type": "text/plain" },
      body: "Error: " + (err?.message || "unknown"),
    };
  }
};
